patch:
--- a/crates/aqua/src/native/gpu.rs
+++ b/crates/aqua/src/native/gpu.rs
@@ -253,6 +253,7 @@
             usage as f64 / 1048576.0,
             backend.ledger().render()
         );
+        eprintln!("aqua-persistent {label} {:?}", backend.persistent_stats());
     }

     fn adopt_recovery(&mut self) -> Result<(), GpuError> {
@@ -616,6 +617,14 @@
             startup_mark("frame_present_begin");
         }
         let feedback = self.frames.present(side, frame);
+        if std::env::var_os("AQUA_LEDGER").is_some() {
+            static LEDGER_PRESENTS: std::sync::atomic::AtomicU32 =
+                std::sync::atomic::AtomicU32::new(0);
+            let count = LEDGER_PRESENTS.fetch_add(1, Ordering::Relaxed) + 1;
+            if count <= 8 || count % 100 == 0 {
+                self.frames.backend().print_ledger(&format!("present-{count}"));
+            }
+        }
         if !cfg!(feature = "d3d12")
             && self.composition.is_none()
             && self.viewport != side.viewport()
